/// <summary>
/// Controller for the <c>ConDemoNoteReindexService</c> operation. Defaults the execution mode
/// to <c>SysOperationExecutionMode::ScheduledBatch</c> so the work runs in the batch server.
/// </summary>
class ConDemoNoteReindexController extends SysOperationServiceController
{
}

Method.Source:
/// <summary>
/// Initializes a new instance of the <c>ConDemoNoteReindexController</c> class.
/// </summary>
protected void new()
{
    super();

    this.parmClassName(classStr(ConDemoNoteReindexService));
    this.parmMethodName(methodStr(ConDemoNoteReindexService, process));
    this.parmExecutionMode(SysOperationExecutionMode::ScheduledBatch);
}

/// <summary>
/// Constructs a new instance of the <c>ConDemoNoteReindexController</c> class.
/// </summary>
/// <returns>The controller instance.</returns>
public static ConDemoNoteReindexController construct()
{
    return new ConDemoNoteReindexController();
}

/// <summary>
/// Entry point of the operation.
/// </summary>
/// <param name = "_args">The arguments passed by the caller.</param>
public static void main(Args _args)
{
    ConDemoNoteReindexController controller = ConDemoNoteReindexController::construct();

    controller.parmArgs(_args);
    controller.startOperation();
}
